import psycopg2, sqlite3, ast, re
from collections import defaultdict
pg=psycopg2.connect(host='dab-postgres', port=5432, user='postgres', password='postgres', dbname='bookreview_db')
cur=pg.cursor(); cur.execute('select book_id,title,details from books_info')
books=[]
for bid,title,details in cur.fetchall(): books.append((int(re.search(r'_(\d+)$',bid).group(1)),bid,title,details or ''))
cur.close(); pg.close()
sq=sqlite3.connect('/workspace/query_dataset/review_query.db')
rev=defaultdict(list)
for rating,pid in sq.execute('select rating,purchase_id from review'):
    rev[int(re.search(r'_(\d+)$',pid).group(1))].append(rating)
sq.close()
months='January|February|March|April|May|June|July|August|September|October|November|December|Jan\.?|Feb\.?|Mar\.?|Apr\.?|Jun\.?|Jul\.?|Aug\.?|Sep\.?|Sept\.?|Oct\.?|Nov\.?|Dec\.?' 
pat=re.compile(r'\b(' + months + r')\s+([0-9]{1,2}),\s*([0-9]{4})\b', re.I)
def year(d):
    m=pat.search(d); return int(m.group(3)) if m else None
bookavg=defaultdict(list); rowavg=defaultdict(list)
for suffix,bid,title,details in books:
    y=year(details)
    if y and rev[suffix]:
        dec=(y//10)*10
        bookavg[dec].append(sum(rev[suffix])/len(rev[suffix]))
        rowavg[dec].extend(rev[suffix])
print('review-row avg eligible')
for dec, vals in sorted(rowavg.items()):
    if len(bookavg[dec])>=10: print(dec, len(bookavg[dec]), len(vals), sum(vals)/len(vals))
